// Edit the values below. (n8n blocks environment variables in nodes by default, so settings live here.)
const cfg = {
  portal_url: 'https://logistricks-portal.vercel.app',
  portal_secret: 'CHANGE_ME',
  gemini_key: 'CHANGE_ME',
  gemini_model: 'gemini-3.6-flash',
}
return [{ json: { ...$input.first().json, cfg } }]

const item = $input.first().json
const b = item.body || item
const secret = (item.headers && (item.headers['x-portal-secret'] || item.headers['X-Portal-Secret'])) || ''
if (!item.cfg || !item.cfg.portal_secret || secret !== item.cfg.portal_secret) return [{ json: { unauthorized: true } }]
if (!b.client_code || !b.from_email) return [{ json: { bad_request: 'client_code and from_email are required' } }]
const body = String(b.body_text || '')
// Only the requester's new text: cut at the first quoted-reply marker.
const cut = body.search(/^(On .{5,200}wrote:|-{2,}\s*Original Message|_{5,}|From:\s.+@.+|>.*)$/m)
const fresh = (cut > 0 ? body.slice(0, cut) : body).trim()
const files = (b.attachments || [])
  .filter((a) => a && a.data_base64 && /^(application\/pdf|image\/(png|jpe?g|webp))$/i.test(String(a.mime_type || '')) && String(a.data_base64).length < 8000000)
  .slice(0, 4)
  .map((a) => ({ filename: a.filename || 'file', mime_type: String(a.mime_type).toLowerCase(), data: String(a.data_base64).replace(/^data:[^,]*,/, '') }))
return [{ json: {
  client_code: b.client_code, from_email: String(b.from_email).toLowerCase(), from_name: b.from_name || '',
  subject: b.subject || '', received_at: b.received_at || new Date().toISOString(),
  fresh_text: fresh.slice(0, 20000), raw_text: body.slice(0, 50000), files,
  intake_source: b.intake_source === 'manual' ? 'manual' : 'automatic', intake_filename: b.intake_filename || null,
} }]

// Calls Gemini from code: retries, tolerant JSON parsing.
const p = $input.first().json
const cfg = $('Config').first().json.cfg
const SYSTEM = "You extract a freight rate request from an email sent by a client's staff or customer. The email may have attachments (PDF / images) that you can read directly; use them as part of the request.\n\nRULES\n1. Extract ONLY what is explicitly written. Never guess. If something is not stated, return null.\n2. Take the requester's NEW text only. Ignore signatures, disclaimers and quoted earlier messages.\n3. modes: any of \"sea\", \"air\", \"land\" that the request asks for. Container sizes (20GP, 40HC), FCL/LCL, ports and B/L terms mean sea; airports, AWB, chargeable weight mean air; trucking / FTL / LTL / cross-border road means land. List a mode you deduced in inferred_fields.\n4. SEA requests: origin_city is the Port of Loading (POL) and destination_city the Port of Discharge (POD). Put the port name (e.g. \"Jebel Ali\", \"Aqaba\", \"Shanghai\") there, not an inland town. If the email gives a place and a port, use the port.\n5. incoterm: the 3-letter code (EXW, FOB, CIF, ...), upper case.\n6. pickup_address: for EXW (ex-works) requests, the full street address where the goods are collected, exactly as written (company, street, city, postcode, country). Null when not given. A city alone is not an address.\n7. equipment: container type and count as written (e.g. \"2 x 40HC\"); cargo_type: what is shipped; weight with its unit as written; dimensions as written; quantity (pieces/pallets/containers) as written.\n8. urgency: \"urgent\" only if the email asks for urgent / ASAP / immediate handling, otherwise \"standard\". aog true only for an aircraft-on-ground request; dgr true only for dangerous goods.\n9. special_requirements: a list of the explicit extra requirements stated by the requester that are NOT captured in any other field. Never repeat origin, destination, incoterm, pickup address, containers or equipment, cargo type, weight, dimensions, quantity, BL type, preferred carrier, urgency, AOG or DGR here, because those have their own fields. Write EACH item as Label: value, with a short label of 2 to 4 words. Examples of items: Free time at POD: at least 10 days / Temperature: +18C / Insurance: required / Door delivery: yes / PO number: 450012345. Common labels: Free time, Temperature, Packaging, Handling, Documents, Certificates, References, PO number, Insurance, Door delivery, Customs, Routing, Remarks. Create a new short label when none fits. Use an empty list when there are none. availability_questions: questions the requester asks about space, schedule or availability.\n10. confidence: \"high\" when origin, destination and cargo are clear; \"medium\" when one is unclear; \"low\" when several are missing or the mail is not a rate request.\n11. is_rate_request: false for out-of-office replies, newsletters, invoices, or anything that is not asking for a freight rate.\n12. inferred_fields: list of fields you had to deduce rather than read.\n13. Return JSON only, matching the schema."
const SCHEMA = {"type":"OBJECT","properties":{"is_rate_request":{"type":"BOOLEAN"},"sender_name":{"type":"STRING","nullable":true},"sender_phone":{"type":"STRING","nullable":true},"modes":{"type":"ARRAY","items":{"type":"STRING","enum":["sea","air","land"]}},"origin_city":{"type":"STRING","nullable":true},"origin_country":{"type":"STRING","nullable":true},"destination_city":{"type":"STRING","nullable":true},"destination_country":{"type":"STRING","nullable":true},"cargo_type":{"type":"STRING","nullable":true},"equipment":{"type":"STRING","nullable":true},"weight":{"type":"STRING","nullable":true},"quantity":{"type":"STRING","nullable":true},"dimensions":{"type":"STRING","nullable":true},"incoterm":{"type":"STRING","nullable":true},"pickup_address":{"type":"STRING","nullable":true},"bl_type":{"type":"STRING","nullable":true},"preferred_carrier":{"type":"STRING","nullable":true},"urgency":{"type":"STRING","enum":["standard","urgent"]},"aog":{"type":"BOOLEAN"},"dgr":{"type":"BOOLEAN"},"special_requirements":{"type":"ARRAY","items":{"type":"STRING"}},"availability_questions":{"type":"ARRAY","items":{"type":"STRING"}},"confidence":{"type":"STRING","enum":["high","medium","low"]},"inferred_fields":{"type":"ARRAY","items":{"type":"STRING"}}},"required":["is_rate_request","modes","urgency","aog","dgr","confidence","inferred_fields"]}
const text = 'Freight request email\nFrom: ' + p.from_name + ' <' + p.from_email + '>\nSubject: ' + p.subject + '\nReceived: ' + p.received_at + '\n\n' + p.fresh_text
const parts = [{ text: text + (p.files.length ? '\n\nAttached files (read them): ' + p.files.map((f) => f.filename).join(', ') : '') }]
for (const f of p.files) parts.push({ inline_data: { mime_type: f.mime_type, data: f.data } })
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const url = 'https://generativelanguage.googleapis.com/v1beta/models/' + cfg.gemini_model + ':generateContent?key=' + cfg.gemini_key
async function call(attempt, useSchema) {
  const gen = { temperature: 0, responseMimeType: 'application/json', thinkingConfig: { thinkingBudget: 0 } }
  if (useSchema) gen.responseSchema = SCHEMA
  const system = useSchema ? SYSTEM : SYSTEM + '\n\nReturn JSON with exactly these fields (schema): ' + JSON.stringify(SCHEMA)
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST', url, headers: { 'Content-Type': 'application/json' }, json: true,
      body: { systemInstruction: { parts: [{ text: system }] }, contents: [{ role: 'user', parts }], generationConfig: gen },
    })
    if (!response.candidates) throw new Error('No candidates returned: ' + JSON.stringify(response))
    const aiText = response.candidates[0].content.parts[0].text
    let ai
    try { ai = JSON.parse(aiText) } catch (e) { ai = JSON.parse(aiText.replace(/```json|```/g, '').trim()) }
    return [{ json: ai }]
  } catch (e) {
    const msg = e.message || String(e)
    if (attempt >= 3) throw new Error('Gemini failed after ' + attempt + ' attempts: ' + msg)
    await sleep(msg.includes('429') ? attempt * 6000 : attempt * 3000)
    return call.call(this, attempt + 1, useSchema && !/400|schema|responseSchema/i.test(msg))
  }
}
return await call.call(this, 1, true)
